nextflow_process {

    name "Test Process PROSEG"
    script "../main.nf"
    process "PROSEG"

    tag "modules"
    tag "modules_nfcore"
    tag "proseg"
    tag "proseg/proseg"
    tag "segmentation"
    tag "cell_segmentation"

    test("proseg - transcripts.csv") {

        when {
            process {
                """
                input[0] = [
                    [id: "test_run_proseg"],
                    file(params.modules_testdata_base_path + "spatial_omics/xenium/homo_sapiens/spatial_gene_expression.csv", checkIfExists: true)
                ]
                input[1] = 'xenium'
                input[2] = ['csv.gz', 'csv.gz', 'csv.gz']
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(
                                    process.out,
                                    unstableKeys: [
                                        "zarr",
                                        "cell_polygons",
                                        "transcript_metadata",
                                        "cell_metadata",
                                        "cell_polygons_layers",
                                        "expected_counts",
                                        "union_cell_polygons"
                                    ]
                                )).match()
                }
            )
        }
    }

    test("proseg stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [id: "test_run_proseg"],
                    file(params.modules_testdata_base_path + "spatial_omics/xenium/homo_sapiens/spatial_gene_expression.csv", checkIfExists: true)
                ]
                input[1] = 'xenium'
                input[2] = ['csv.gz', 'csv.gz', 'csv.gz']
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}
